'use client';
// Tool-container-only route: public writer adapter, never authentication or production data.
import {useCallback,useEffect,useRef,useState} from 'react';import CopyButton from '../components/elements/copy-button';import CopyDemo from '../examples/copy-demo';import '../examples/examples.css';
export default function Page(){const [value,setValue]=useState(' Synthetic original '),[mounted,setMounted]=useState(true),[requests,setRequests]=useState<number[]>([]),[submits,setSubmits]=useState(0),[rows,setRows]=useState(0),sequence=useRef(0),pending=useRef(new Map<number,{resolve:()=>void;reject:(error:Error)=>void}>());const write=useCallback(()=>new Promise<void>((resolve,reject)=>{const id=++sequence.current;pending.current.set(id,{resolve,reject});setRequests(values=>[...values,id]);}),[]);
 useEffect(()=>{const control=(event:Event)=>{const d=(event as CustomEvent).detail;if(d.kind==='resolve')pending.current.get(d.id)?.resolve();if(d.kind==='reject')pending.current.get(d.id)?.reject(new DOMException('Synthetic private failure',d.name??'NotAllowedError'));if(d.kind==='replace')setValue(d.value);if(d.kind==='unmount')setMounted(false);if(d.kind==='remount')setMounted(true);if(d.kind==='ending')window.dispatchEvent(new Event('templux:session-ending'));};window.addEventListener('fixture:copy',control);return()=>window.removeEventListener('fixture:copy',control);},[]);
 return <main><h1>Copy lifecycle fixture</h1><output aria-label="copy requests">{JSON.stringify(requests)}</output><output aria-label="form submits">{submits}</output><output aria-label="row clicks">{rows}</output><form onSubmit={event=>{event.preventDefault();setSubmits(v=>v+1);}}><div onClick={()=>setRows(v=>v+1)}>{mounted&&<CopyButton value={value} label="复制受控合成值" settings={{feedbackMs:1500,emptyMode:'disable'}} write={write}/>}</div></form><CopyDemo settings={{feedbackMs:1500,emptyMode:'disable'}}/></main>;
}
